import re

_WS_CHARS = frozenset(" \t\n\r")
_WS = re.compile(r"[ \t\n\r]*")
_STR_CHUNK = re.compile(r'[^"\\\x00-\x1f]*')
_HEX4 = re.compile(r"[0-9a-fA-F]{4}")
_LOW_ESC = re.compile(r"\\u([dD][c-fC-F][0-9a-fA-F]{2})")
_NUMBER = re.compile(r"-?(?:0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?")
_SIMPLE_ESCAPES = {
    '"': '"',
    "\\": "\\",
    "/": "/",
    "b": "\b",
    "f": "\f",
    "n": "\n",
    "r": "\r",
    "t": "\t",
}
_INT_CHUNK_DIGITS = 4000


def _digits_to_int(digits):
    length = len(digits)
    if length <= _INT_CHUNK_DIGITS:
        return int(digits)
    low_length = length // 2
    high = digits[: length - low_length]
    low = digits[length - low_length:]
    return _digits_to_int(high) * (10 ** low_length) + _digits_to_int(low)


def _parse_int(literal):
    if len(literal) <= _INT_CHUNK_DIGITS:
        return int(literal)
    if literal[0] == "-":
        return -_digits_to_int(literal[1:])
    return _digits_to_int(literal)


def _read_string(text, pos, n):
    # pos は開き引用符の次の位置。閉じ引用符の次の位置とともに値を返す。
    parts = []
    chunk_match = _STR_CHUNK.match
    while True:
        end = chunk_match(text, pos).end()
        if end > pos:
            parts.append(text[pos:end])
        if end >= n:
            raise ValueError("unterminated string")
        ch = text[end]
        if ch == '"':
            if len(parts) == 1:
                return parts[0], end + 1
            return "".join(parts), end + 1
        if ch != "\\":
            raise ValueError("control character in string")
        if end + 1 >= n:
            raise ValueError("unterminated escape")
        esc = text[end + 1]
        simple = _SIMPLE_ESCAPES.get(esc)
        if simple is not None:
            parts.append(simple)
            pos = end + 2
            continue
        if esc != "u":
            raise ValueError("invalid escape")
        hex_match = _HEX4.match(text, end + 2)
        if hex_match is None:
            raise ValueError("invalid unicode escape")
        code = int(hex_match.group(), 16)
        pos = end + 6
        if 0xD800 <= code <= 0xDBFF:
            low_match = _LOW_ESC.match(text, pos)
            if low_match is None:
                raise ValueError("unpaired high surrogate")
            low = int(low_match.group(1), 16)
            code = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00)
            pos = low_match.end()
        elif 0xDC00 <= code <= 0xDFFF:
            raise ValueError("unpaired low surrogate")
        parts.append(chr(code))


def _read_member_key(text, pos, n):
    # オブジェクトのキーと ':' を読み、値の先頭（空白を飛ばしたあと）の位置を返す。
    if pos >= n or text[pos] != '"':
        raise ValueError("object key must be a string")
    key, pos = _read_string(text, pos + 1, n)
    pos = _WS.match(text, pos).end()
    if pos >= n or text[pos] != ":":
        raise ValueError("expected ':'")
    pos = _WS.match(text, pos + 1).end()
    return key, pos


def parse_json(text: str) -> object:
    n = len(text)
    ws = _WS.match
    stack = []  # 作りかけのコンテナ（list か dict）
    keys = []  # stack と対応。dict なら今のキー、list なら None
    pos = ws(text, 0).end()

    while True:
        # ここで値を 1 つ読み始める
        if pos >= n:
            raise ValueError("unexpected end of input")
        ch = text[pos]
        if ch == '"':
            value, pos = _read_string(text, pos + 1, n)
        elif ch == "{":
            pos = ws(text, pos + 1).end()
            if pos < n and text[pos] == "}":
                value = {}
                pos += 1
            else:
                key, pos = _read_member_key(text, pos, n)
                stack.append({})
                keys.append(key)
                continue
        elif ch == "[":
            pos = ws(text, pos + 1).end()
            if pos < n and text[pos] == "]":
                value = []
                pos += 1
            else:
                stack.append([])
                keys.append(None)
                continue
        elif ch in "-0123456789":
            match = _NUMBER.match(text, pos)
            if match is None:
                raise ValueError("invalid number")
            literal = match.group()
            pos = match.end()
            if match.group(1) is not None or match.group(2) is not None:
                value = float(literal)
            else:
                value = _parse_int(literal)
        elif text.startswith("true", pos):
            value = True
            pos += 4
        elif text.startswith("false", pos):
            value = False
            pos += 5
        elif text.startswith("null", pos):
            value = None
            pos += 4
        else:
            raise ValueError("unexpected character")

        # 値が 1 つ読めた。親に入れて、閉じるか、次の値へ進む
        while True:
            if pos < n and text[pos] in _WS_CHARS:
                pos = ws(text, pos).end()
            if not stack:
                if pos != n:
                    raise ValueError("extra data after value")
                return value
            if pos >= n:
                raise ValueError("unexpected end of input")
            ch = text[pos]
            container = stack[-1]
            key = keys[-1]
            if key is None:
                container.append(value)
                if ch == ",":
                    pos = ws(text, pos + 1).end()
                    break
                if ch == "]":
                    pos += 1
                    value = stack.pop()
                    keys.pop()
                    continue
                raise ValueError("expected ',' or ']'")
            else:
                if key in container:
                    raise ValueError("duplicate key")
                container[key] = value
                if ch == ",":
                    pos = ws(text, pos + 1).end()
                    keys[-1], pos = _read_member_key(text, pos, n)
                    break
                if ch == "}":
                    pos += 1
                    value = stack.pop()
                    keys.pop()
                    continue
                raise ValueError("expected ',' or '}'")
